cat > ./probe.tmp.mjs <<'EOF'
import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage();
const failures = [];
page.on('requestfailed', r => failures.push(['FAILED', r.url(), r.failure()?.errorText]));
page.on('response', r => { if (r.status() >= 400) failures.push(['HTTP '+r.status(), r.url()]); });
for (const p of ['index','products','pricing','orders','about','contact']) {
  await page.goto(`http://127.0.0.1:${process.env.PORT}/${p}.html`);
  await page.waitForLoadState('networkidle');
  const info = await page.evaluate(() => {
    const h1 = document.querySelector('h1');
    const body = getComputedStyle(document.body);
    return {
      font: body.fontFamily,
      check400: document.fonts.check('16px "Acme Sans"'),
      h1font: getComputedStyle(h1).fontFamily,
      loaded: [...document.fonts].map(f => `${f.family} ${f.weight} ${f.status}`),
      bodyBg: body.backgroundColor,
      h1Size: getComputedStyle(h1).fontSize,
      h1Weight: getComputedStyle(h1).fontWeight,
    };
  });
  console.log(p, JSON.stringify(info));
}
console.log('failures:', JSON.stringify(failures, null, 2));
await browser.close();
EOF
PORT=4199 node server.js > "$TMPDIR/server.log" 2>&1 & SRV=$!; sleep 1; PORT=4199 node ./probe.tmp.mjs; kill $SRV

