cat > ./overflow.tmp.mjs <<'EOF'
import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
for (const p of ['index','products','pricing','orders','about','contact']) {
  await page.goto(`http://127.0.0.1:${process.env.PORT}/${p}.html`);
  const issues = await page.evaluate(() => {
    const out = [];
    const vw = document.documentElement.clientWidth;
    for (const el of document.querySelectorAll('body *')) {
      const b = el.getBoundingClientRect();
      if (b.width === 0 || b.height === 0) continue;
      if (b.right > vw + 1 || b.left < -1) out.push(['viewport', el.tagName+'.'+el.className, Math.round(b.left), Math.round(b.right)]);
      if (el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflowX === 'visible') out.push(['overflow', el.tagName+'.'+el.className, el.scrollWidth, el.clientWidth]);
      if (el.tagName === 'IMG' && (!el.complete || el.naturalWidth === 0)) out.push(['brokenimg', el.src]);
    }
    return out.slice(0, 20);
  });
  console.log(p, JSON.stringify(issues));
}
await browser.close();
EOF
