python3 - <<'EOF'
import glob
for f in glob.glob('site/**/*', recursive=True):
    import os
    if os.path.isdir(f) or f.endswith(('.png','.woff2')): continue
    d=open(f,'rb').read()
    issues=[]
    if d.startswith(b'\xef\xbb\xbf'): issues.append('BOM')
    if b'\r' in d: issues.append('CRLF')
    if b'\t' in d: issues.append('TAB')
    nonascii=sorted(set(b for b in d if b>127))
    if nonascii: issues.append('nonascii: '+','.join(hex(b) for b in nonascii))
    if b'  \n' in d: issues.append('trailing spaces')
    print(f, issues)
EOF

