cat > ./verify.tmp.mjs <<'EOF'
import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto(`http://127.0.0.1:${process.env.PORT}/index.html`);
const info = await page.evaluate(async () => {
  await document.fonts.ready;
  const probe = (w) => {
    const span = document.createElement('span');
    span.style.cssText = `font-family:'Acme Sans';font-size:40px;font-weight:${w};position:absolute;visibility:hidden;white-space:nowrap`;
    span.textContent = 'Small things make';
    document.body.appendChild(span);
    const width = span.getBoundingClientRect().width;
    span.remove();
    return +width.toFixed(2);
  };
  return {
    faces: [...document.fonts].map(f => `${f.family} ${f.weight} ${f.status}`),
    widths: { w400: probe(400), w600: probe(600), w700: probe(700), w800: probe(800) },
    h1Weight: getComputedStyle(document.querySelector('h1')).fontWeight,
  };
});
console.log(JSON.stringify(info, null, 2));
await page.screenshot({ path: `${process.env.TMPDIR}/fixed-index.png`, fullPage: true });
await browser.close();
EOF
