const browser = await chromium.launch();
for (const width of [390, 760, 1280]) {
  const page = await browser.newPage({ viewport: { width, height: 900 } });
  for (const p of ['index','products','pricing','orders','about','contact']) {
    await page.goto(`http://127.0.0.1:${process.env.PORT}/${p}.html`);
    const bad = await page.evaluate(() => ({
      overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
      broken: [...document.images].some(i => !i.complete || i.naturalWidth === 0),
      font: document.fonts.check('800 16px "Acme Sans"'),
    }));
    if (bad.overflow || bad.broken || !bad.font) console.log('ISSUE', width, p, JSON.stringify(bad));
  }
  console.log(width, 'checked');
  await page.close();
}
await browser.close();
EOF
